from pathlib import Path

import sounddevice as sd
import torch

import text_to_speech

# %% ../nbs/00_recorded_speech.ipynb #08908e93
def record(seconds, sr=44_100):
    "Record `seconds` of mono audio from the default microphone."
    input(f"Press Enter, then make a sound for {seconds} seconds...")
    x = sd.rec(int(seconds * sr), samplerate=sr, channels=1, dtype="float32")
    sd.wait()
    return x[:, 0]

# %% ../nbs/00_recorded_speech.ipynb #bb5514f3
DATA = Path(text_to_speech.__file__).parents[1] / "data"


def default_device():
    return "mps" if torch.backends.mps.is_available() else "cuda" if torch.cuda.is_available() else "cpu"
